1: // What: the first-run explainer copy and its one local preference.
2: // Why: the player must learn the limits before the camera opens, and must not meet the explainer twice.
3: // Removed: the first screen would be a wall of controls, and the fair-play line would live only in the README.
4: 
5: export const EXPLAINER_TITLE = 'ChessPulse reviews your chess session after you play.';
6: 
7: export const EXPLAINER_INTRO =
8:   'It watches your pulse through the camera while you play on chess.com, then shows your pulse next to your moves, so you can see whether a bad stretch lined up with a stressful stretch.';
9: 
10: export interface ExplainerStep {
11:   readonly title: string;
12:   readonly body: string;
13: }
14: 
15: /** Five steps, in the order Setup repeats. Step one is the current position on the first screen. */
16: export const EXPLAINER_STEPS: readonly ExplainerStep[] = [
17:   {
18:     title: 'Allow the camera.',
19:     body: 'Nothing is recorded. No video or image is saved. Only pulse numbers are stored, on this computer.',
20:   },
21:   {
22:     title: 'Check your framing.',
23:     body: 'Sit so your upper chest is in view and you are the only face on screen.',
24:   },
25:   {
26:     title: 'Play on chess.com.',
27:     body: 'ChessPulse does not show anything during a game. Mark each game end with one button.',
28:   },
29:   {
30:     title: 'Stop and paste your games.',
31:     body: 'Copy the PGNs from chess.com, oldest first.',
32:   },
33:   {
34:     title: 'Read your review.',
35:     body: 'One verdict line, one timeline, and the accuracy in calm and elevated pulse periods.',
36:   },
37: ];
38: 
39: /** The limits are stated as plainly as the features, including the fair-play line. */
40: export const EXPLAINER_NEVERS: readonly string[] = [
41:   'It does not give advice during a rated game.',
42:   'It does not diagnose anything or give medical advice.',
43:   'It does not upload your data. Everything stays local.',
44: ];
45: 
46: export const EXPLAINER_PREFERENCE_KEY = 'chesspulse.explainer.seen.v1';
47: 
48: /** The two methods the page needs. A real `localStorage` satisfies this without a DOM type here. */
49: export interface PreferenceStore {
50:   getItem(key: string): string | null;
51:   setItem(key: string, value: string): void;
52: }
53: 
54: /**
55:  * A missing, unreadable, or throwing store means "not seen": the safe failure is to explain the
56:  * product again, never to hide the consent and fair-play lines behind a broken preference.
57:  */
58: export function readExplainerSeen(store: PreferenceStore | null | undefined): boolean {
59:   if (!store) return false;
60:   try {
61:     return store.getItem(EXPLAINER_PREFERENCE_KEY) === 'true';
62:   } catch {
63:     return false;
64:   }
65: }
66: 
67: /** Returns false when the preference could not be saved; the screen still closes for this run. */
68: export function rememberExplainerSeen(store: PreferenceStore | null | undefined): boolean {
69:   if (!store) return false;
70:   try {
71:     store.setItem(EXPLAINER_PREFERENCE_KEY, 'true');
72:     return true;
73:   } catch {
74:     return false;
75:   }
76: }

