1: // What: the first-run and Help explainer. One copy source, two heading levels.
2: // Why: the limits and the five-step process must be readable before the camera opens and again later.
3: // Removed: the first screen would be controls with no explanation, and Help would repeat stale copy.
4: import { useId } from 'react';
5: import {
6:   EXPLAINER_INTRO,
7:   EXPLAINER_NEVERS,
8:   EXPLAINER_STEPS,
9:   EXPLAINER_TITLE,
10: } from '../shared/onboarding';
11: 
12: export function Explainer({
13:   showProgress = false,
14:   headingLevel = 1,
15: }: {
16:   showProgress?: boolean;
17:   headingLevel?: 1 | 2;
18: }) {
19:   const baseId = useId();
20:   const howId = `${baseId}-how`;
21:   const neverId = `${baseId}-never`;
22: 
23:   return (
24:     <section className="explainer" aria-label="How ChessPulse works">
25:       {headingLevel === 1 ? (
26:         <h1 className="explainer-title">{EXPLAINER_TITLE}</h1>
27:       ) : (
28:         <h2 className="explainer-title">{EXPLAINER_TITLE}</h2>
29:       )}
30:       <p className="explainer-intro">{EXPLAINER_INTRO}</p>
31: 
32:       <section aria-labelledby={howId}>
33:         {headingLevel === 1 ? (
34:           <h2 id={howId}>How it works</h2>
35:         ) : (
36:           <h3 id={howId}>How it works</h3>
37:         )}
38:         <ol className="explainer-steps">
39:           {EXPLAINER_STEPS.map((step, index) => (
40:             <li
41:               key={step.title}
42:               aria-current={showProgress && index === 0 ? 'step' : undefined}
43:             >
44:               <strong>{step.title}</strong> {step.body}
45:               {showProgress && index === 0 ? <span className="here">You are here</span> : null}
46:             </li>
47:           ))}
48:         </ol>
49:       </section>
50: 
51:       <section aria-labelledby={neverId}>
52:         {headingLevel === 1 ? (
53:           <h2 id={neverId}>What ChessPulse never does</h2>
54:         ) : (
55:           <h3 id={neverId}>What ChessPulse never does</h3>
56:         )}
57:         <ul className="explainer-nevers">
58:           {EXPLAINER_NEVERS.map((line) => (
59:             <li key={line}>{line}</li>
60:           ))}
61:         </ul>
62:       </section>
63:     </section>
64:   );
65: }

