1: // What: the renderer's one navigation state machine and its status priority.
2: // Why: a reload, a late session event, and a screen change must land in one place, not in scattered state.
3: // Removed: two states could disagree about consent or which screen is open, and the urgent message could be hidden.
4: import type {
5:   PulseSample,
6:   ReportResult,
7:   ValidationMessage,
8: } from './contracts.js';
9: import { CONFIDENCE_FLOOR } from './sensing.js';
10: 
11: /** The screens in the §3.1 diagram. `setup`, `sessions` and `help` are filled in by later W4 steps. */
12: export const SCREENS = [
13:   'home',
14:   'setup',
15:   'sensing',
16:   'stopped',
17:   'games',
18:   'review',
19:   'sessions',
20:   'help',
21: ] as const;
22: 
23: export type Screen = (typeof SCREENS)[number];
24: export type FlowTone = 'error' | 'note' | 'default';
25: 
26: export interface ActiveSessionState {
27:   id: string;
28:   startedAtEpochMs: number;
29:   betweenGames: boolean;
30: }
31: 
32: export interface ReviewState {
33:   sessionId: string;
34:   result: ReportResult | null;
35:   building: boolean;
36:   error: string | null;
37:   progress: { scored: number; total: number } | null;
38:   cancelling: boolean;
39: }
40: 
41: export interface FlowState {
42:   screen: Screen;
43:   consent: boolean;
44:   session: ActiveSessionState | null;
45:   stoppedSessionId: string | null;
46:   /** The paste survives Games -> Review -> Games. It is cleared only by a new session. */
47:   draft: string[];
48:   review: ReviewState | null;
49:   explainerSeen: boolean;
50:   /** Where Help returns to. Help is a detour, not a replacement for the working screen. */
51:   helpReturn: Screen | null;
52:   notice: string;
53:   error: string | null;
54:   sdkError: string | null;
55: }
56: 
57: export type FlowEvent =
58:   | {
59:       type: 'hydrated';
60:       consent: boolean;
61:       session: { id: string; startedAtEpochMs: number; betweenGames: boolean } | null;
62:     }
63:   | { type: 'explainerDismissed' }
64:   | { type: 'consentChanged'; granted: boolean }
65:   | { type: 'sessionStarted'; sessionId: string; startedAtEpochMs: number }
66:   | { type: 'sessionStopped'; sessionId: string; notice: string }
67:   | { type: 'openHome' }
68:   | { type: 'openSetup' }
69:   | { type: 'openSessions' }
70:   | { type: 'openHelp' }
71:   | { type: 'closeHelp' }
72:   | { type: 'openStopped' }
73:   | { type: 'openGames' }
74:   | { type: 'openReview' }
75:   | { type: 'pasteChanged'; slots: string[] }
76:   | { type: 'reportStarted'; sessionId: string; slots: string[] }
77:   | { type: 'reportProgress'; scored: number; total: number }
78:   | { type: 'reportReady'; result: ReportResult }
79:   | { type: 'reportFailed'; message: string }
80:   | { type: 'reportCancelRequested' }
81:   | { type: 'reportCancelRejected' }
82:   | { type: 'gapChanged'; betweenGames: boolean }
83:   | { type: 'openedSession'; sessionId: string; report: ReportResult | null; games: string[] }
84:   | { type: 'sessionDeleted'; sessionId: string }
85:   | { type: 'notice'; message: string }
86:   | { type: 'error'; message: string }
87:   | { type: 'sdkError'; message: string }
88:   | { type: 'clearSdkError' }
89:   | { type: 'clearError' };
90: 
91: const CONSENT_OFF = 'The camera stays off until you consent.';
92: const CONSENT_ON = 'Consent is on. The camera opens when you start sensing.';
93: 
94: export function initialFlowState(explainerSeen = false): FlowState {
95:   return {
96:     screen: 'home',
97:     consent: false,
98:     session: null,
99:     stoppedSessionId: null,
100:     draft: [],
101:     review: null,
102:     explainerSeen,
103:     helpReturn: null,
104:     notice: CONSENT_OFF,
105:     error: null,
106:     sdkError: null,
107:   };
108: }
109: 
110: /** The session a screen may act on. Review keeps its own id after the live session is gone. */
111: export function currentSessionId(state: FlowState): string | null {
112:   return state.review?.sessionId ?? state.stoppedSessionId ?? state.session?.id ?? null;
113: }
114: 
115: function consentNotice(granted: boolean): string {
116:   return granted ? CONSENT_ON : CONSENT_OFF;
117: }
118: 
119: function activeSession(state: FlowState): ActiveSessionState | null {
120:   return state.session;
121: }
122: 
123: /**
124:  * Applies one event. A transition the diagram does not allow returns the same object, so no caller
125:  * can create a screen the state machine does not recognise.
126:  */
127: export function flowReducer(state: FlowState, event: FlowEvent): FlowState {
128:   switch (event.type) {
129:     case 'hydrated': {
130:       if (state.session || state.stoppedSessionId || state.review) return state;
131:       return {
132:         ...state,
133:         consent: event.consent,
134:         session: event.session
135:           ? {
136:               id: event.session.id,
137:               startedAtEpochMs: event.session.startedAtEpochMs,
138:               betweenGames: event.session.betweenGames,
139:             }
140:           : null,
141:         stoppedSessionId: event.session ? null : state.stoppedSessionId,
142:         screen: event.session ? 'sensing' : state.screen,
143:         notice: event.session ? 'Waiting for a face.' : consentNotice(event.consent),
144:       };
145:     }
146: 
147:     case 'explainerDismissed':
148:       return state.explainerSeen ? state : { ...state, explainerSeen: true };
149: 
150:     case 'consentChanged':
151:       return {
152:         ...state,
153:         consent: event.granted,
154:         notice: consentNotice(event.granted),
155:       };
156: 
157:     case 'sessionStarted':
158:       return {
159:         ...state,
160:         screen: 'sensing',
161:         session: {
162:           id: event.sessionId,
163:           startedAtEpochMs: event.startedAtEpochMs,
164:           betweenGames: false,
165:         },
166:         stoppedSessionId: null,
167:         draft: [],
168:         review: null,
169:         error: null,
170:         notice: 'Waiting for a face.',
171:       };
