62:   const [validation, setValidation] = useState<ValidationMessage | null>(null);
63:   const [coachMessage, setCoachMessage] = useState<CoachMessage | null>(null);
64:   const [insightState, setInsightState] = useState<InsightViewState>({ status: 'idle' });
65:   const bridge = window.chesspulse;
66:   const grantedNow = useRef(false);
67:   const startPending = useRef(false);
68:   const revokedDuringStart = useRef(false);
69:   const reportRequestSeq = useRef(0);
70:   const insightRequestSeq = useRef(0);
71:   const sessionIdRef = useRef<string | null>(null);
72:   const terminalSessionRef = useRef<string | null>(null);
73:   const supersededSessions = useRef<Set<string>>(new Set());
74:   const setupFocus = useRef(false);
75:   const consentButtonRef = useRef<HTMLButtonElement | null>(null);
76:   const startButtonRef = useRef<HTMLButtonElement | null>(null);
77: 
78:   function resetInsight(): void {
79:     insightRequestSeq.current += 1;
80:     setInsightState({ status: 'idle' });
81:   }
82: 
83:   function adoptSession(nextId: string, startedAtEpochMs: number): void {
84:     resetInsight();
85:     setCoachMessage(null);
86:     if (sessionIdRef.current === nextId) return;
87:     if (sessionIdRef.current) supersededSessions.current.add(sessionIdRef.current);
88:     sessionIdRef.current = nextId;
89:     terminalSessionRef.current = null;
90:     reportRequestSeq.current += 1;
91:     dispatch({ type: 'sessionStarted', sessionId: nextId, startedAtEpochMs });
92:     setSamples([]);
93:     setSelectedIndex(null);
94:     setValidation(null);
95:   }
96: 
97:   function settleSession(nextId: string, notice: string): void {
98:     resetInsight();
99:     setCoachMessage(null);
100:     if (sessionIdRef.current && sessionIdRef.current !== nextId) {
101:       supersededSessions.current.add(sessionIdRef.current);
102:     }
103:     sessionIdRef.current = nextId;
104:     reportRequestSeq.current += 1;
105:     dispatch({ type: 'sessionStopped', sessionId: nextId, notice });
106:   }
107: 
108:   function dismissExplainer(startSetup: boolean): void {
109:     rememberExplainerSeen(preferenceStore());
110:     setupFocus.current = startSetup;
111:     dispatch({ type: 'explainerDismissed' });
112:   }
113: 
114:   // What: one load-time read of main's consent and live-session state.
115:   // Why: a reloaded page must not render consent off while main still holds it, nor forget a session.
116:   useEffect(() => {
117:     if (!bridge) return;
118:     void bridge
119:       .getAppState()
120:       .then((raw) => {
121:         const parsed = appStateSchema.safeParse(raw);
122:         if (!parsed.success) return;
123:         const { consent, session } = parsed.data;
124:         grantedNow.current = consent.granted;
125:         if (session.active && session.sessionId && session.startedAtEpochMs !== null) {
126:           sessionIdRef.current = session.sessionId;
127:           terminalSessionRef.current = null;
128:         }
129:         dispatch({
130:           type: 'hydrated',
131:           consent: consent.granted,
132:           session:
133:             session.active && session.sessionId && session.startedAtEpochMs !== null
134:               ? {
135:                   id: session.sessionId,
136:                   startedAtEpochMs: session.startedAtEpochMs,
137:                   betweenGames: session.betweenGames,
138:                 }
139:               : null,
140:         });
141:       })
142:       .catch(() => {
143:         // A failed state read leaves the page in its honest default: camera off, Home.
144:       });
145:   }, [bridge]);
146: 
147:   // The consent switch follows the reducer even when main changes it behind the page.
148:   useEffect(() => {
149:     grantedNow.current = flow.consent;
150:   }, [flow.consent]);
151: 
152:   useEffect(() => {
153:     if (!bridge) return undefined;
154:     return bridge.onSamples((batch) => {
155:       const parsed = sampleBatchSchema.safeParse(batch);
156:       if (!parsed.success) return;
157:       setSamples((current) => [...current, ...parsed.data]);
158:       dispatch({ type: 'clearSdkError' });
159:     });
160:   }, [bridge]);
161: 
162:   useEffect(() => {
163:     if (!bridge) return undefined;
164:     return bridge.onCoachMessage((message) => {
165:       const parsed = coachMessageSchema.safeParse(message);
166:       if (parsed.success) setCoachMessage(parsed.data);
167:     });
168:   }, [bridge]);
169: 
170:   useEffect(() => {
171:     if (!bridge) return undefined;
172:     return bridge.onValidation((message) => {
173:       setValidation(message);
174:       if (message.code === 0) dispatch({ type: 'clearSdkError' });
175:     });
176:   }, [bridge]);
177: 
178:   useEffect(() => {
179:     if (!bridge) return undefined;
180:     return bridge.onSdkError((info) => {
181:       // Kept apart from operation errors, which no sensing event may clear.
182:       dispatch({ type: 'sdkError', message: info.message });
183:       if (info.retryable) return;
184:       void (async () => {
185:         try {
186:           const meta = await bridge.stopSession();
187:           settleSession(meta.id, stoppedNote(meta));
188:         } catch {
189:           // The session may already be closed. The message above still stands, and the screen
190:           // must not keep claiming it is sensing.
191:           if (sessionIdRef.current) {
192:             dispatch({
193:               type: 'sessionStopped',
194:               sessionId: sessionIdRef.current,
195:               notice: 'The session stopped after a sensing error.',
196:             });
197:           } else {
198:             dispatch({ type: 'openStopped' });
199:           }
200:         }
201:       })();
202:     });
203:   }, [bridge]);
204: 
205:   useEffect(() => {
206:     if (!bridge) return undefined;
207:     return bridge.onSessionEnded((event) => {
208:       const parsed = sessionEndedSchema.safeParse(event);
209:       if (!parsed.success) return;
210:       // A late event from a session the page has already replaced must not switch the screen back.
211:       if (supersededSessions.current.has(parsed.data.sessionId)) return;
212:       settleSession(parsed.data.sessionId, parsed.data.message);
213:       terminalSessionRef.current = parsed.data.sessionId;
214:       dispatch({ type: 'clearError' });
215:     });
216:   }, [bridge]);
217: 
218:   useEffect(() => {
219:     if (!bridge) return undefined;
220:     return bridge.onSessionStarted((event) => {
221:       const parsed = sessionStartedSchema.safeParse(event);
222:       if (!parsed.success) return;
223:       if (terminalSessionRef.current === parsed.data.sessionId) return;
224:       if (supersededSessions.current.has(parsed.data.sessionId)) return;
225:       // A page that already adopted a different live session must not switch to a late start event.
226:       if (sessionIdRef.current && sessionIdRef.current !== parsed.data.sessionId) return;
227:       // The event means main opened a session, which requires consent. Set both before the
228:       // session, so a reload that missed the invoke reply does not show an off consent switch.
229:       grantedNow.current = true;
230:       dispatch({ type: 'consentChanged', granted: true });
231:       adoptSession(parsed.data.sessionId, parsed.data.startedAtEpochMs);
232:     });
233:   }, [bridge]);
234: 
235:   useEffect(() => {
236:     if (!bridge) return undefined;
237:     return bridge.onReportProgress((progress) => {
238:       const parsed = reportProgressSchema.safeParse(progress);
239:       if (!parsed.success || parsed.data.sessionId !== sessionIdRef.current) return;
240:       dispatch({
241:         type: 'reportProgress',
242:         scored: parsed.data.scored,
243:         total: parsed.data.total,
244:       });
245:     });
246:   }, [bridge]);
247: 
248:   // Focus follows the screen and the first-run explanation, so a click never leaves it on removed
249:   // content. When Start setup dismisses the explanation, the next effect moves focus to step one.
250:   useEffect(() => {
251:     const heading = document.querySelector<HTMLElement>('main h1');
252:     if (!heading) return;
253:     heading.tabIndex = -1;
254:     heading.focus();
255:   }, [flow.screen, flow.explainerSeen]);
256: 
257:   useEffect(() => {
258:     if (!flow.explainerSeen || !setupFocus.current) return;
259:     setupFocus.current = false;
260:     const target = flow.consent ? startButtonRef.current : consentButtonRef.current;
261:     target?.focus();
262:   }, [flow.explainerSeen, flow.consent]);
263: 
264:   const sessionId = currentSessionId(flow);
265:   const status = statusFor({
266:     error: flow.error,
267:     sdkError: flow.sdkError,
268:     screen: flow.screen,
269:     hint: sensingHint(samples, validation),
270:     notice: flow.notice,
271:   });
272: 
273:   async function onConsent(): Promise<void> {
274:     if (!bridge) {
275:       dispatch({
276:         type: 'notice',
277:         message: 'This page is open outside the ChessPulse window. The camera stays off.',
278:       });
279:       return;
280:     }
281:     const revoking = grantedNow.current;
282:     if (revoking && startPending.current) revokedDuringStart.current = true;
283:     let stopFailed = false;
284:     if (flow.screen === 'sensing' || (revoking && startPending.current)) {
285:       try {
286:         const meta = await bridge.stopSession();
287:         settleSession(meta.id, stoppedNote(meta));
288:         dispatch({ type: 'clearError' });
289:       } catch {
290:         stopFailed = true;
291:         dispatch({ type: 'error', message: 'The session could not be stopped.' });
292:       }
293:     }
294:     try {
295:       const next = await bridge.setConsent(!grantedNow.current);
296:       if (!stopFailed) dispatch({ type: 'clearError' });
297:       grantedNow.current = next.granted;
298:       dispatch({ type: 'consentChanged', granted: next.granted });
299:     } catch {
300:       dispatch({
301:         type: 'notice',
302:         message: 'Consent could not be saved. The camera state is unchanged.',
303:       });
304:     }
305:   }
306: 
307:   async function onStart(): Promise<void> {
308:     if (!bridge) {
309:       dispatch({
310:         type: 'notice',
311:         message: 'This page is open outside the ChessPulse window. The camera stays off.',
312:       });
313:       return;
314:     }
315:     revokedDuringStart.current = false;
316:     startPending.current = true;
317:     try {
318:       const started = await bridge.startSession(timeControl);
319:       adoptSession(started.sessionId, started.startedAtEpochMs);
320:       // A terminal event may have arrived before the start response completed.
321:       if (terminalSessionRef.current === started.sessionId) return;
322:       if (revokedDuringStart.current || !grantedNow.current) {
323:         try {
324:           const meta = await bridge.stopSession();
325:           settleSession(meta.id, stoppedNote(meta));
326:         } catch {
327:           // Consent revocation has normally finalized the session already, so stopSession
328:           // rejects. The screen must not keep claiming it is sensing a session that is gone.
329:           settleSession(started.sessionId, 'The session stopped after consent was withdrawn.');
330:         }
331:         return;
332:       }
333:     } catch (caught: unknown) {
334:       if (!revokedDuringStart.current && grantedNow.current) {
335:         dispatch({ type: 'error', message: readIpcError(caught, 'session_failed') });
336:       }
337:     } finally {
338:       startPending.current = false;
339:     }
340:   }
341: 
342:   async function onStop(): Promise<void> {
343:     if (!bridge || flow.screen !== 'sensing') return;
344:     try {
345:       const meta = await bridge.stopSession();
346:       settleSession(meta.id, stoppedNote(meta));
347:       dispatch({ type: 'clearError' });
348:     } catch {
349:       dispatch({ type: 'error', message: 'The session could not be stopped.' });
350:     }
351:   }
352: 
353:   async function onGapToggle(): Promise<void> {
354:     if (!bridge || flow.screen !== 'sensing' || gapPending || !flow.session) return;
355:     setGapPending(true);
356:     dispatch({ type: 'clearError' });
357:     // A line from the previous gap must never appear during the next game. Clear before the call
358:     // so an immediate coach event for the new gap cannot be erased by its own response.
359:     setCoachMessage(null);
360:     try {
361:       const result = await bridge.setBetweenGames(!flow.session.betweenGames);
362:       dispatch({ type: 'gapChanged', betweenGames: result.betweenGames });
363:     } catch (caught: unknown) {
364:       dispatch({ type: 'error', message: readIpcError(caught, 'session_failed') });
365:     } finally {
366:       setGapPending(false);
367:     }
368:   }
369: 
370:   async function onInsightRequest(provider: AiProvider, text: string): Promise<void> {
371:     if (!bridge || !sessionId) return;
372:     const seq = ++insightRequestSeq.current;
373:     setInsightState({ status: 'loading' });
374:     try {
375:       const raw = await bridge.requestInsight({ sessionId, provider, text });
376:       if (seq !== insightRequestSeq.current) return;
377:       const parsed = insightResultSchema.safeParse(raw);
378:       if (!parsed.success) {
379:         setInsightState({
380:           status: 'error',
381:           message: 'The reading returned an unexpected shape. The report is unchanged.',
382:         });
383:       } else if (parsed.data.disabled) {
384:         setInsightState({ status: 'disabled', reason: parsed.data.reason });
385:       } else {
386:         setInsightState({ status: 'ready', text: parsed.data.text });
387:       }
388:     } catch (caught: unknown) {
389:       if (seq !== insightRequestSeq.current) return;
390:       setInsightState({
391:         status: 'error',
392:         message: readIpcError(caught, 'ai_unavailable'),
393:       });
394:     }
395:   }
396: 
397:   async function onInsightCancel(): Promise<void> {
398:     if (!bridge || !sessionId) return;
399:     insightRequestSeq.current += 1;
400:     setInsightState({ status: 'idle' });
401:     try {
402:       await bridge.cancelInsight(sessionId);
403:     } catch {
404:       // The timeout still bounds the call; its result is ignored after the sequence change.
405:     }
406:   }
407: 
408:   async function onPasteContinue(pgns: string[], _validation: PasteValidation): Promise<void> {
409:     if (!sessionId) {
410:       dispatch({ type: 'error', message: 'No stored session is available for this report.' });
411:       return;
412:     }
413:     if (bridge) void bridge.cancelInsight(sessionId).catch(() => undefined);
414:     resetInsight();
415:     const seq = ++reportRequestSeq.current;
416:     dispatch({ type: 'reportStarted', sessionId, slots: pgns });
417:     if (!bridge) {
418:       dispatch({ type: 'reportFailed', message: 'This page is open outside the ChessPulse window.' });
419:       return;
420:     }
421:     try {
422:       const raw = await bridge.buildReport(sessionId, pgns);
423:       if (seq !== reportRequestSeq.current) return;
424:       const parsed = reportResultSchema.safeParse(raw);
425:       if (!parsed.success) {
426:         dispatch({ type: 'reportFailed', message: 'The report returned an unexpected shape.' });
427:         return;
428:       }
429:       dispatch({ type: 'reportReady', result: parsed.data });
430:     } catch (caught: unknown) {
431:       if (seq !== reportRequestSeq.current) return;
432:       dispatch({ type: 'reportFailed', message: readIpcError(caught, 'report_failed') });
433:     }
434:   }
435: 
436:   async function onCancelReport(): Promise<void> {
437:     if (!bridge || !sessionId || !flow.review?.building || flow.review.cancelling) return;
438:     dispatch({ type: 'reportCancelRequested' });
439:     try {
440:       const result = await bridge.cancelReport(sessionId);
441:       if (!result.cancelled) dispatch({ type: 'reportCancelRejected' });
442:     } catch {
443:       // Let the player retry if the cancel request never reached main.
444:       dispatch({ type: 'reportCancelRejected' });
445:     }
446:   }
447: 
448:   async function onCopyDiagnostics(): Promise<void> {
449:     if (!bridge) {
450:       dispatch({
451:         type: 'notice',
452:         message: 'This page is open outside the ChessPulse window. Diagnostics are unavailable.',
453:       });
454:       return;
455:     }
456:     try {
457:       await bridge.copyDiagnostics();
458:       dispatch({ type: 'clearError' });
459:       dispatch({
460:         type: 'notice',
461:         message: 'Diagnostics copied. They contain no games, pulse samples, or keys.',
462:       });
463:     } catch (caught: unknown) {
464:       dispatch({ type: 'error', message: readIpcError(caught, 'internal') });
465:     }
466:   }
467: 
468:   if (flow.screen === 'home' && !flow.explainerSeen) {
469:     return (
470:       <main>
471:         <p className="label">ChessPulse</p>
472:         <Explainer showProgress />
473:         <StatusRegion status={status} />
474:         <div className="actions">
475:           {/* S47 leaves the destination as the existing start controls; S48 replaces it with Setup. */}
476:           <button type="button" className="primary-btn" onClick={() => dismissExplainer(true)}>
477:             Start setup
478:           </button>
479:           <button type="button" onClick={() => dismissExplainer(false)}>
480:             Skip for now
481:           </button>
482:         </div>
483:       </main>
484:     );
485:   }
486: 
487:   if (flow.screen === 'help') {
488:     return (
489:       <main>
490:         <p className="label">ChessPulse · Help</p>
491:         <h1>Help</h1>
492:         {flow.session ? <p className="indicator">Sensing</p> : null}
493:         <StatusRegion status={status} />
494:         <Explainer headingLevel={2} />
495:         <div className="actions">
496:           <button type="button" className="primary-btn" onClick={() => void onCopyDiagnostics()}>
497:             Copy diagnostics
498:           </button>
499:           <button type="button" onClick={() => dispatch({ type: 'closeHelp' })}>
500:             Back
501:           </button>
502:         </div>
503:       </main>
504:     );
505:   }
506: 
507:   if (flow.screen === 'games') {
508:     return (
509:       <main>
510:         {status.tone === 'error' ? <StatusRegion status={status} /> : null}
511:         <PasteScreen
512:           sessionId={sessionId}
513:           initialSlots={flow.draft.length > 0 ? flow.draft : undefined}
514:           onBack={(currentSlots) => {
515:             dispatch({ type: 'pasteChanged', slots: currentSlots });
516:             dispatch({ type: 'openStopped' });
517:           }}
518:           onContinue={(pgns, validation) => {
519:             void onPasteContinue(pgns, validation);
520:           }}
521:           onHelp={() => dispatch({ type: 'openHelp' })}
522:           onSlotsChange={(slots) => dispatch({ type: 'pasteChanged', slots })}
523:         />
524:       </main>
525:     );
526:   }
527: 
528:   if (flow.screen === 'review') {
529:     const review = flow.review;
530:     return (
531:       <main>
532:         <p className="label">ChessPulse · Report</p>
533:         {status.tone === 'error' ? <StatusRegion status={status} /> : null}
534:         {review?.building ? (
535:           <>
536:             <h1>Building report.</h1>
537:             <p aria-live="polite">
538:               {review.progress && review.progress.total > 0
539:                 ? `Scored ${review.progress.scored} of ${review.progress.total} positions…`
540:                 : 'Scoring positions locally with Stockfish…'}
541:             </p>
542:             <button type="button" onClick={() => void onCancelReport()} disabled={review.cancelling}>
543:               {review.cancelling ? 'Cancelling…' : 'Cancel report'}
544:             </button>
545:           </>
546:         ) : review?.error ? (
547:           <>
548:             <h1>Report unavailable.</h1>
549:             <div className="refusal-panel" role="alert">
550:               <p>{review.error}</p>
551:             </div>
552:           </>
553:         ) : review?.result?.ok ? (
554:           <div className="report-layout">
555:             <VerdictLine report={review.result} />
556:             <Timeline key={`ok-${review.result.sessionId}`} result={review.result} />
557:             <BandBars report={review.result} />
558:             <GameList report={review.result} />
559:             <InsightPanel
560:               state={insightState}
561:               onRequest={(provider, text) => void onInsightRequest(provider, text)}
562:               onCancel={() => void onInsightCancel()}
563:             />
564:           </div>
565:         ) : (
566:           <>
567:             <h1>{review?.result ? 'Review withheld.' : 'Session timeline.'}</h1>
568:             <Timeline key={`refusal-${sessionId ?? ''}`} result={review?.result ?? null} />
569:           </>
570:         )}
571:         <div className="actions">
572:           <button type="button" onClick={() => dispatch({ type: 'openGames' })}>
573:             Edit pasted PGNs
574:           </button>
575:           <button type="button" onClick={() => dispatch({ type: 'openStopped' })}>
576:             Back to session
577:           </button>
578:           <button type="button" onClick={() => dispatch({ type: 'openHelp' })}>
579:             Help
580:           </button>
581:         </div>
582:       </main>
583:     );
584:   }
585: 
586:   const sensing = flow.screen === 'sensing';
587:   const stopped = flow.screen === 'stopped';
588:   return (
589:     <main>
590:       <p className="label">ChessPulse</p>
591:       <h1>{sensing ? 'Sensing.' : stopped ? 'Sensing stopped.' : 'Sensing has not started.'}</h1>
592:       {sensing ? <p className="indicator">Sensing</p> : null}
593:       <StatusRegion status={status} />
594:       {flow.consent ? <CameraPreview sensing={sensing} /> : null}
595:       <SensingStrip samples={samples} selectedIndex={selectedIndex} onSelect={setSelectedIndex} />
596:       {sensing && flow.session?.betweenGames ? <CoachLine message={coachMessage} /> : null}
597:       {!sensing && !stopped ? (
598:         <div className="choices" role="group" aria-label="Time control">
599:           {TIME_CONTROLS.map((control) => (
600:             <button
601:               key={control}
602:               type="button"
603:               aria-pressed={control === timeControl}
604:               onClick={() => setTimeControl(control)}
605:             >
606:               {control}
607:             </button>
608:           ))}
609:         </div>
610:       ) : null}
611:       <div className="actions">
612:         {stopped ? (
613:           <button type="button" className="primary-btn" onClick={() => dispatch({ type: 'openGames' })}>
614:             Paste PGNs
615:           </button>
616:         ) : null}
617:         {sensing ? (
618:           <>
619:             <button type="button" disabled={gapPending} onClick={() => void onGapToggle()}>
620:               {flow.session?.betweenGames ? 'Next game started' : 'Game ended'}
621:             </button>
622:             <button type="button" onClick={() => void onStop()}>
623:               Stop sensing
624:             </button>
625:           </>
626:         ) : (
627:           <button
628:             ref={startButtonRef}
629:             type="button"
630:             disabled={!flow.consent}
631:             onClick={() => void onStart()}
632:           >
633:             Start sensing
634:           </button>
635:         )}
636:         <button
637:           ref={consentButtonRef}
638:           type="button"
639:           aria-pressed={flow.consent}
640:           onClick={() => void onConsent()}
641:         >
642:           {flow.consent ? 'Revoke camera consent' : 'Allow the camera'}
643:         </button>
644:         <button type="button" onClick={() => dispatch({ type: 'openHelp' })}>
645:           Help
646:         </button>
647:       </div>
648:     </main>
649:   );
650: }
651: 
652: function StatusRegion({ status }: { status: StatusLine }) {
653:   // One node, one priority order. `role="alert"` is not swapped in, because assistive tech does
654:   // not reliably re-announce an element whose role changes; the live level carries urgency.
655:   return (
656:     <p className="status-line" role="status" aria-live={status.urgent ? 'assertive' : 'polite'}>
657:       {status.text}
658:     </p>
659:   );
660: }
661: 
662: function stoppedNote(meta: SessionMeta): string {  const baseline = meta.baselineBpm === undefined ? 'No baseline.' : `Baseline ${formatNumber(meta.baselineBpm)} bpm.`;
663:   const coverage = meta.coverage === undefined ? 'No coverage.' : `Coverage ${formatNumber(meta.coverage.pct)}%.`;
664:   return `${baseline} ${coverage}`;
665: }
666: 
667: function formatNumber(value: number): string {
668:   return Number.isInteger(value) ? String(value) : value.toFixed(1);
669: }

