13: 
14: const INITIAL_SLOTS = 3;
15: const MAX_SLOTS = 20;
16: 
17: const STATE_LABEL: Record<PasteState, string> = {
18:   empty: 'Empty',
19:   partial: 'Partial',
20:   out_of_order: 'Out of order',
