37:     state: 'empty',
38:     order: 'none',
39:     clockless: false,
40:     canBuild: false,
41:     message: 'Paste chess.com PGNs oldest first.',
42:     summary: { total: 0, includedInStats: 0, aborted: 0, abandoned: 0 },
43:     slots: Array.from({ length: count }, (_item, slotIndex) => ({
44:       slotIndex,
45:       status: 'empty' as const,
46:     })),
47:   };
48: }
49: 
50: export function PasteScreen({
51:   sessionId,
52:   initialSlots,
53:   onBack,
54:   onContinue,
55:   onHelp,
56:   onSlotsChange,
57: }: {
58:   sessionId: string | null;
59:   initialSlots?: string[];
60:   onBack: (slots: string[]) => void;
61:   onContinue: (pgns: string[], validation: PasteValidation) => void;
62:   onHelp?: () => void;
63:   onSlotsChange?: (slots: string[]) => void;
64: }) {
65:   const [slots, setSlots] = useState<string[]>(() =>
66:     initialSlots && initialSlots.length > 0
67:       ? initialSlots
68:       : Array.from({ length: INITIAL_SLOTS }, () => ''),
69:   );
70:   const [validation, setValidation] = useState<PasteValidation>(() => emptyValidation(slots.length));
71:   const [validating, setValidating] = useState(false);
72:   const [bridgeError, setBridgeError] = useState<string | null>(null);
73:   const requestSeq = useRef(0);
74:   const baseId = useId();
75:   const bridge = window.chesspulse;
76: 
77:   useEffect(() => {
78:     const seq = ++requestSeq.current;
79:     if (!bridge) {
80:       setValidating(false);
81:       setBridgeError('This page is open outside the ChessPulse window. Paste validation is unavailable.');
82:       return;
83:     }
84:     if (slots.every((text) => text.trim().length === 0)) {
85:       setValidating(false);
86:       setBridgeError(null);
87:       setValidation(emptyValidation(slots.length));
88:       return;
89:     }
90:     setValidating(true);
91:     setBridgeError(null);
92:     void bridge
93:       .validatePgns(slots)
94:       .then((raw) => {
95:         if (seq !== requestSeq.current) return;
96:         const parsed = pasteValidationSchema.safeParse(raw);
97:         if (!parsed.success) {
98:           setBridgeError('Validation returned an unexpected result.');
99:           return;
100:         }
101:         setValidation(parsed.data);
102:       })
103:       .catch((error: unknown) => {
104:         if (seq !== requestSeq.current) return;
105:         setBridgeError(readIpcError(error, 'pgn_invalid'));
106:       })
107:       .finally(() => {
108:         if (seq === requestSeq.current) setValidating(false);
109:       });
110:   }, [bridge, slots]);
111: 
112:   function updateSlot(index: number, value: string): void {
113:     const next = slots.map((item, i) => (i === index ? value : item));
114:     setSlots(next);
115:     onSlotsChange?.(next);
116:   }
117: 
118:   function addSlot(): void {
119:     if (slots.length >= MAX_SLOTS) return;
120:     const next = [...slots, ''];
121:     setSlots(next);
122:     onSlotsChange?.(next);
