149:   const bannerTone = toneFor(bridgeError ? 'invalid' : validation.state);
150:   const canContinue = Boolean(bridge) && !validating && !bridgeError && validation.canBuild;
151: 
152:   return (
153:     <section className="paste-screen" aria-labelledby={`${baseId}-heading`}>
154:       <p className="label">ChessPulse · Paste PGNs</p>
155:       <h1 id={`${baseId}-heading`}>Paste your games in order.</h1>
