162:         <div className="banner-head">
163:           <span className={`state-tag tone-${bannerTone}`}>
164:             {validating ? 'Checking' : bridgeError ? 'Unavailable' : STATE_LABEL[validation.state]}
165:           </span>
166:           {validation.summary.total > 0 && !bridgeError ? (
167:             <span className="banner-counts">{formatCounts(validation.summary)}</span>
168:           ) : null}
169:         </div>
170:         <p className="banner-message">{bridgeError ?? validation.message}</p>
171:         {!bridgeError && validation.order === 'unverified' && validation.summary.total > 0 ? (
172:           <p className="banner-sub">
173:             No timestamps in these PGNs. Order follows the boxes below (oldest first).
174:           </p>
175:         ) : null}
176:       </div>
177: 
178:       <ol className="slot-list">
179:         {slots.map((text, index) => {
180:           const slotInfo: PasteSlot = validation.slots[index] ?? { slotIndex: index, status: 'empty' };
181:           const fieldId = `${baseId}-slot-${index}`;
182:           const errorId = `${baseId}-slot-error-${index}`;
183:           const hasError = slotInfo.status === 'invalid' || slotInfo.status === 'order_error';
184: 
185:           return (
186:             <li key={index} className={`paste-slot status-${slotInfo.status}`}>
187:               <div className="slot-header">
188:                 <div className="slot-title">
189:                   <label htmlFor={fieldId}>Game {index + 1}</label>
190:                   <SlotBadge slot={slotInfo} />
191:                 </div>
192:                 <div className="slot-controls">
193:                   <button
194:                     type="button"
195:                     className="small-btn"
196:                     disabled={index === 0}
197:                     aria-label={`Move game ${index + 1} up`}
198:                     onClick={() => moveSlot(index, -1)}
199:                   >
200:                     Move up
201:                   </button>
202:                   <button
203:                     type="button"
204:                     className="small-btn"
205:                     disabled={index === slots.length - 1}
206:                     aria-label={`Move game ${index + 1} down`}
207:                     onClick={() => moveSlot(index, 1)}
208:                   >
209:                     Move down
210:                   </button>
211:                   {text.length > 0 ? (
212:                     <button
213:                       type="button"
214:                       className="small-btn"
215:                       aria-label={`Clear game ${index + 1}`}
216:                       onClick={() => updateSlot(index, '')}
217:                     >
218:                       Clear
219:                     </button>
220:                   ) : null}
221:                   <button
222:                     type="button"
223:                     className="small-btn"
224:                     disabled={slots.length <= 1}
225:                     aria-label={`Remove game ${index + 1}`}
226:                     onClick={() => removeSlot(index)}
227:                   >
228:                     Remove
229:                   </button>
230:                 </div>
231:               </div>
232: 
233:               {slotInfo.status === 'valid' || slotInfo.status === 'order_error' ? (
234:                 <GameSummaryRow game={slotInfo.game} />
235:               ) : null}
236: 
237:               <textarea
238:                 id={fieldId}
239:                 rows={4}
240:                 spellCheck={false}
241:                 placeholder={`Paste Game ${index + 1} PGN here`}
242:                 value={text}
243:                 aria-invalid={hasError}
244:                 aria-describedby={hasError ? errorId : undefined}
245:                 onChange={(event) => updateSlot(index, event.target.value)}
246:               />
247: 
248:               {hasError ? (
249:                 <p id={errorId} className="slot-error" role="alert">
250:                   {slotInfo.message}
251:                 </p>
252:               ) : null}
253:             </li>
254:           );
255:         })}
256:       </ol>
257: 
258:       <div className="actions">
259:         <button type="button" className="primary-btn" disabled={!canContinue} onClick={handleContinue}>
260:           Continue to report
261:         </button>
262:         <button type="button" disabled={slots.length >= MAX_SLOTS} onClick={addSlot}>
263:           Add game ({slots.length}/{MAX_SLOTS})
264:         </button>
265:         <button type="button" onClick={() => onBack(slots)}>
266:           Back to session
267:         </button>
268:         {onHelp ? (
269:           <button type="button" onClick={onHelp}>
270:             Help
271:           </button>
272:         ) : null}
273:       </div>
274:     </section>
275:   );
276: }
277: 
278: function SlotBadge({ slot }: { slot: PasteSlot }) {
279:   if (slot.status === 'empty') {
280:     return <span className="slot-badge tone-neutral">Empty</span>;
281:   }
282:   if (slot.status === 'valid') {
283:     return (
284:       <span className="slot-badge tone-ok">
285:         <svg viewBox="0 0 14 14" width="14" height="14" aria-hidden="true">
286:           <path d="M2.5 7.5L5.5 10.5L11.5 3.5" fill="none" stroke="currentColor" strokeWidth="1.75" />
287:         </svg>
288:         Valid
289:       </span>
290:     );
291:   }
292:   if (slot.status === 'order_error') {
293:     return <span className="slot-badge tone-warn">Out of order</span>;
294:   }
295:   return <span className="slot-badge tone-warn">Invalid</span>;
296: }
297: 
298: function GameSummaryRow({ game }: { game: PasteGameSummary }) {
299:   const players =
300:     game.white || game.black
301:       ? `${game.white || 'Unknown'} vs ${game.black || 'Unknown'}`
302:       : 'Players unnamed';
303:   const moves = `${game.moveCount} ${game.moveCount === 1 ? 'ply' : 'plies'}`;
304:   const clocks =
305:     game.moveCount === 0
306:       ? 'No moves'
307:       : !game.hasClocks
308:         ? 'No clocks'
309:         : game.partialClocks
310:           ? 'Partial clocks'
311:           : 'Clocks OK';
312: 
313:   return (
314:     <div className="slot-meta">
315:       <span className="meta-players">{players}</span>
316:       <span className="meta-detail">
317:         {game.result} · {ENDING_LABEL[game.ending]} · {moves} · {clocks}
318:         {game.timeControl ? ` · ${game.timeControl}` : ''}
319:       </span>
320:       {!game.includeInStats ? (
321:         <span className="meta-excluded">Excluded from accuracy</span>
322:       ) : null}
323:     </div>
324:   );
325: }
326: 
327: function formatCounts(summary: PasteValidation['summary']): string {
328:   const parts = [
329:     `${summary.total} ${summary.total === 1 ? 'game' : 'games'}`,
330:     `${summary.includedInStats} in accuracy`,
331:   ];
332:   if (summary.aborted > 0) parts.push(`${summary.aborted} aborted`);
333:   if (summary.abandoned > 0) parts.push(`${summary.abandoned} abandoned`);
334:   return parts.join(' · ');
335: }
336: 
337: function toneFor(state: PasteState): 'neutral' | 'ok' | 'warn' {
338:   if (state === 'valid') return 'ok';
339:   if (state === 'out_of_order' || state === 'clockless' || state === 'invalid') return 'warn';
340:   return 'neutral';
341: }

