1: // What: the camera preview, fed by the frames the main process already measures.
2: // Why: the player must see their own framing, and the page must not open a second camera stream.
3: // Removed: the player would be aiming blind, and a second stream would fight the SDK for the device.
4: import { useEffect, useRef, useState } from 'react';
5: import type { PreviewFrame } from '../shared/contracts';
6: import { lightNote, previewBoost } from '../shared/preview';
7: 
8: /** How long without a frame before the preview admits it is waiting. */
9: const STALE_MS = 2_000;
10: const LIGHT_UPDATE_MS = 500;
11: 
12: export function CameraPreview({ sensing }: { sensing: boolean }) {
13:   const canvasRef = useRef<HTMLCanvasElement | null>(null);
14:   const lastFrameAt = useRef(0);
15:   const lastLightAt = useRef(0);
16:   const [light, setLight] = useState<number | null>(null);
17:   const [hasFrame, setHasFrame] = useState(false);
18:   const [stale, setStale] = useState(false);
19:   const bridge = window.chesspulse;
20: 
21:   useEffect(() => {
22:     if (!bridge) return undefined;
23:     return bridge.onPreview((frame: PreviewFrame) => {
24:       const canvas = canvasRef.current;
25:       if (!canvas) return;
26:       const context = canvas.getContext('2d');
27:       if (!context) return;
28:       if (canvas.width !== frame.width) canvas.width = frame.width;
29:       if (canvas.height !== frame.height) canvas.height = frame.height;
30:       const pixels = new Uint8ClampedArray(frame.rgba.byteLength);
31:       pixels.set(frame.rgba);
32:       context.putImageData(new ImageData(pixels, frame.width, frame.height), 0, 0);
33:       lastFrameAt.current = Date.now();
34:       setHasFrame((current) => current || true);
35:       if (Date.now() - lastLightAt.current > LIGHT_UPDATE_MS) {
36:         lastLightAt.current = Date.now();
37:         setLight(frame.light);
38:       }
39:     });
40:   }, [bridge]);
41: 
42:   useEffect(() => {
43:     if (!sensing) {
44:       setStale(false);
45:       return undefined;
46:     }
47:     const timer = window.setInterval(() => {
48:       setStale(Date.now() - lastFrameAt.current > STALE_MS);
49:     }, 500);
50:     return () => window.clearInterval(timer);
51:   }, [sensing]);
52: 
53:   const boost = previewBoost(light);
54: 
55:   return (
56:     <figure className="camera">
57:       <canvas
58:         ref={canvasRef}
59:         className="camera-video"
60:         width={320}
61:         height={180}
62:         style={boost > 1 ? { filter: `brightness(${boost.toFixed(2)}) contrast(1.15)` } : undefined}
63:         role="img"
64:         aria-label="Camera preview. Nothing is recorded."
65:       />
66:       <figcaption className="hint">
67:         {!sensing
68:           ? 'The camera opens when you start sensing.'
69:           : !hasFrame || stale
70:             ? 'Waiting for the camera…'
71:             : lightNote(light)}
72:       </figcaption>
73:     </figure>
74:   );
75: }

