1: // What: stores the explicit consent flag and answers the page on one channel.
2: // Why: the camera permission handler reads this flag, and the page cannot set it by any other path.
3: // Removed: revoking consent would not reach the process that grants the camera.
4: import { consentStateSchema } from '../shared/contracts.js';
5: import { registerInvokeChannel } from './ipc-registry.js';
6: import { grantsMediaPermission } from './permission.js';
7: 
8: let consentGranted = false;
9: 
10: export function currentConsent(): boolean {
11:   return consentGranted;
12: }
13: 
14: export interface ConsentHooks {
15:   /** Called after consent is withdrawn, so the process holding the camera can let go. */
16:   onRevoked?: () => void;
17: }
18: 
19: export interface ConsentOptions {
20:   appFileUrl: string;
21:   devOrigin?: string;
22: }
23: 
24: export function registerConsentHandler(options: ConsentOptions, hooks: ConsentHooks = {}): void {
25:   registerInvokeChannel('consentSet', (event, payload) => {
26:     const wasGranted = consentGranted;
27:     consentGranted = payload.granted;
28:     if (wasGranted && !consentGranted) {
29:       try {
30:         hooks.onRevoked?.();
31:       } catch {
32:         // The flag is already off; the page cannot re-open the camera through this path.
33:       }
34:     }
35:     return consentStateSchema.parse({
36:       granted: consentGranted,
37:       cameraAllowed: grantsMediaPermission({
38:         permission: 'media',
39:         requestingUrl: event.senderFrame?.url,
40:         appFileUrl: options.appFileUrl,
41:         devOrigin: options.devOrigin,
42:         consentGranted,
43:         isMainFrame: true,
44:         mediaTypes: ['video'],
45:       }),
46:     });
47:   });
48: }

